// ye-compose-ui: Compose foundation for ye* native apps. Tokens come from
// ../../build/<app>/YeTokens.kt (generated by tokens/build.mjs); pick the app set
// with -PyeApp=<name> (default "base").
plugins {
    id("com.android.library")
    id("org.jetbrains.kotlin.android")
    id("org.jetbrains.kotlin.plugin.compose")
}

val yeApp = (findProperty("yeApp") as String?) ?: "base"

android {
    namespace = "ye.designsystem.compose"
    compileSdk = 35
    defaultConfig { minSdk = 29 }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
    sourceSets["main"].kotlin.srcDir(rootDir.resolve("../../build/$yeApp").also {
        require(it.resolve("YeTokens.kt").exists()) { "Run `npm run tokens` first: $it/YeTokens.kt missing" }
    }.absolutePath)
    testOptions { unitTests.isReturnDefaultValues = true }
}
kotlin { jvmToolchain(17) }

dependencies {
    val bom = platform("androidx.compose:compose-bom:2024.12.01")
    implementation(bom)
    api("androidx.compose.ui:ui")
    api("androidx.compose.animation:animation")
    api("androidx.compose.foundation:foundation")
    implementation("androidx.compose.material3:material3")
    testImplementation("junit:junit:4.13.2")
}
